require 'test_helper'

class LegacySessionCompatibilityTest < ActionDispatch::IntegrationTest
  setup do
    # Generated by Rails 7.2.4 using an explicitly public, test-only key.
    # Keep the historical cookie/token unchanged so future upgrades must read it.
    @legacy = JSON.parse(File.read(Rails.root.join('test/fixtures/rails_7_2_session.json')))
    # Rails replaces request-level key-generator overrides with env_config.
    # Scope the public fixture key to these tests and restore it afterward.
    @original_key_generator = Rails.application.env_config.fetch('action_dispatch.key_generator')
    Rails.application.env_config['action_dispatch.key_generator'] = ActiveSupport::CachingKeyGenerator.new(
      ActiveSupport::KeyGenerator.new(@legacy.fetch('secret_key_base'), iterations: 1000)
    )
    @original_forgery_protection = ActionController::Base.allow_forgery_protection
    ActionController::Base.allow_forgery_protection = true
    https!
  end

  teardown do
    Rails.application.env_config['action_dispatch.key_generator'] = @original_key_generator
    ActionController::Base.allow_forgery_protection = @original_forgery_protection
  end

  test 'restores Rails 7.2 session data and accepts its CSRF token' do
    get csrf_token_path(locale: :en),
        headers: { 'Cookie' => @legacy.fetch('cookie') }

    assert_response :success
    assert_equal 'IN', request.session[:calculator_nationality_code]

    patch calculator_preferences_path(locale: :en),
          params: { nationality_code: 'DE', destination: 'trips', authenticity_token: @legacy.fetch('csrf_token') },
          headers: { 'Cookie' => @legacy.fetch('cookie') }

    assert_redirected_to visits_path(locale: :en)
    assert_equal 'DE', request.session[:calculator_nationality_code]
  end

  test 'rejects a forged CSRF token with the legacy session cookie' do
    assert_raises(ActionController::InvalidAuthenticityToken) do
      patch calculator_preferences_path(locale: :en),
            params: { nationality_code: 'DE', destination: 'trips', authenticity_token: 'invalid' },
            headers: { 'Cookie' => @legacy.fetch('cookie') }
    end
  end
end
